/**
 * Landmark tracking for captures (video assessment, photo set, bench): one rest frame is the
 * reference; every later frame is drawn into the reference's face crop with the head motion undone,
 * and the reference landmarks are tracked into it (see track.ts for why detection alone is not enough).
 */
import {
  LID_TRACKED_MIN,
  SIDE,
  buildRestReference,
  measureLive,
  taskSignal,
  type FrameObservation,
  type MovementTaskId,
  type QualityThresholds,
  type RestReference,
  type TaskId,
} from '../core';
import { DEFAULT_METHOD, RAFT_TASKS, RAFT_VIDEO_FRAMES, type TrackMethod } from './method';
import { mirrorClosures, type Detect } from './mirror';
import { raftBox, raftCrop, raftObservation, type RaftBox, type RaftCrop, type RaftEngine } from './raft';
import { FINE_TASKS, FINE_TRACK, TRACK_DEFAULTS, cropFor, cropTransform, pyramid, toRef, trackAligned, type Gray, type TrackExperiment, type TrackRef } from './track';

const LIDS = { left: SIDE.left.lidPairs.flat(), right: SIDE.right.lidPairs.flat() };

export interface Grabbed {
  obs: FrameObservation;
  gray: Gray;
}

const hasFace = (o: FrameObservation) => o.landmarks.length >= 468 * 3;

export class CaptureTracker {
  ref: TrackRef | null = null;
  /** The same rest frame on the finer crop, for the FINE_TASKS (FPA-GEOM 0.6.0). */
  fineRef: TrackRef | null = null;
  /** Mean share of points kept by the last `track` call (for logs and the bench). */
  lastKept = 0;
  /** Evaluation only (tools/eval): experimental tracking switches; the app leaves this unset. */
  experiment?: TrackExperiment;
  /** Evaluation only: the quality gate used to pick frames (the app uses the default). */
  quality?: QualityThresholds;
  private canvas: HTMLCanvasElement | null = null;
  /** Frames picked per task (gray crops with their tracked observations), for the eye-closure mirror step. */
  private picked = new Map<string, { grays: Gray[]; obs: FrameObservation[] }>();
  /** SEA-RAFT hybrid (method 'raft'): the rest crop, and per task the most expressive frames' crops (top RAFT_POOL). */
  private raft: { box: RaftBox; rest: RaftCrop; restRef: RestReference } | null = null;
  private raftPool = new Map<string, { obs: FrameObservation; crop: RaftCrop; s: number }[]>();
  private raftPick = new Map<string, (RaftCrop | null)[]>();
  /** Frames per SEA-RAFT task handed to the analysis (photo sets have one per photo anyway). */
  raftFrames = RAFT_VIDEO_FRAMES;

  constructor(readonly method: TrackMethod = DEFAULT_METHOD) {}

  reset(): void {
    this.ref = null;
    this.fineRef = null;
    this.picked.clear();
    this.raft = null;
    this.raftPool.clear();
    this.raftPick.clear();
  }

  /** Makes `obs` (a valid rest frame of `src`) the reference. */
  setRef(src: CanvasImageSource, obs: FrameObservation): void {
    if (!hasFace(obs)) return;
    const crop = cropFor(obs, this.experiment?.cropIpd);
    const gray = this.draw(src, crop.w, crop.h, cropTransform(crop, { s: 1, c: 1, sn: 0, tx: 0, ty: 0 }));
    this.ref = gray ? { obs, crop, pyr: pyramid(gray, this.experiment?.levels ?? TRACK_DEFAULTS.levels), gray } : null;
    this.fineRef = null;
    if (this.ref && !this.experiment && this.method !== 'v050') {
      const fc = cropFor(obs, FINE_TRACK.cropIpd);
      const fg = this.draw(src, fc.w, fc.h, cropTransform(fc, { s: 1, c: 1, sn: 0, tx: 0, ty: 0 }));
      this.fineRef = fg ? { obs, crop: fc, pyr: pyramid(fg, FINE_TRACK.levels), gray: fg } : null;
    }
    this.raft = null;
    this.raftPool.clear();
    if (this.ref && this.method === 'raft') {
      const box = raftBox(obs);
      const rest = raftCrop(src, box);
      const restRef = buildRestReference([obs, obs, obs], this.quality);
      if (rest && restRef) this.raft = { box, rest, restRef };
    }
  }

  /**
   * The frame drawn into the reference crop (null without a reference or a face). Frames of a FINE_TASKS task go into
   * the finer crop (FPA-GEOM 0.6.0); `track` follows them from the fine reference.
   */
  grab(src: CanvasImageSource, obs: FrameObservation, task?: string): Gray | null {
    if (!this.ref || !hasFace(obs)) return null;
    const fine = !!task && FINE_TASKS.has(task) && !!this.fineRef;
    const ref = fine ? this.fineRef! : this.ref;
    const g = this.draw(src, ref.crop.w, ref.crop.h, cropTransform(ref.crop, toRef(ref.obs, obs)));
    if (g && task && this.raft && RAFT_TASKS.has(task)) this.keepRaft(src, obs, task);
    return g && fine ? { ...g, fine: true } : g;
  }

  /** SEA-RAFT crop of a frame if it is among the task's most expressive so far (the frames trackTask will pick). */
  private keepRaft(src: CanvasImageSource, obs: FrameObservation, task: string): void {
    const v = measureLive(task as MovementTaskId, this.raft!.restRef, obs, this.quality);
    if (!v) return;
    const s = taskSignal(v);
    const pool = this.raftPool.get(task) ?? [];
    this.raftPool.set(task, pool);
    const cap = Math.max(this.raftFrames, 1) + 4;
    if (pool.length >= cap) {
      const low = pool.reduce((m, x, i) => (x.s < pool[m]!.s ? i : m), 0);
      if (s <= pool[low]!.s) return;
      pool.splice(low, 1);
    }
    const crop = raftCrop(src, this.raft!.box);
    if (crop) pool.push({ obs, crop, s });
  }

  /**
   * SEA-RAFT hybrid (method 'raft'): the frames picked for `task` are re-measured with the optical flow from the rest
   * crop (in place, on the observations already handed out; frames without a crop keep the tracker's points). Run
   * after trackTask; returns the number of model runs.
   */
  async addFlow(task: string, engine: RaftEngine, onPair?: () => void): Promise<number> {
    const p = this.picked.get(task);
    const crops = this.raftPick.get(task);
    if (!this.raft || !this.ref || !p || !crops) return 0;
    let n = 0;
    for (let i = 0; i < p.obs.length; i++) {
      const crop = crops[i];
      const o = p.obs[i];
      if (!crop || !o) continue;
      const flow = await engine.flow(this.raft.rest, crop);
      (o as { landmarks: ArrayLike<number> }).landmarks = raftObservation(this.ref.obs, o, this.raft.box, flow).landmarks;
      n++;
      onPair?.();
    }
    this.raftPick.delete(task);
    this.raftPool.delete(task);
    return n;
  }

  /** Forgets what was kept for `task` (a retaken step starts over: its SEA-RAFT crops are of the rejected attempt). */
  resetTask(task: string): void {
    this.picked.delete(task);
    this.raftPool.delete(task);
    this.raftPick.delete(task);
  }

  /** Model runs addFlow will make for `task` (for a progress count). */
  flowPairs(task: string): number {
    return (this.raftPick.get(task) ?? []).filter(Boolean).length;
  }

  /** One frame tracked from the reference (the detection itself if tracking is not possible), with its lid-point share. */
  track(g: Grabbed): FrameObservation {
    if (!this.ref) return g.obs;
    const st: { kept: number; lost?: number[] } = { kept: 0 };
    const x = this.experiment;
    const fine = !!g.gray.fine && !!this.fineRef;
    const opt = fine
      ? { ...TRACK_DEFAULTS, half: FINE_TRACK.half, levels: FINE_TRACK.levels }
      : x?.half || x?.levels
        ? { ...TRACK_DEFAULTS, ...(x.half ? { half: x.half } : {}), ...(x.levels ? { levels: x.levels } : {}) }
        : undefined;
    const levels = fine ? FINE_TRACK.levels : (x?.levels ?? TRACK_DEFAULTS.levels);
    const out = trackAligned(fine ? this.fineRef! : this.ref, g.obs, pyramid(g.gray, levels), opt, st, x);
    this.lastKept = st.kept;
    const lost = new Set(st.lost ?? []);
    const share = (ids: number[]) => ids.filter((i) => !lost.has(i)).length / ids.length;
    return { ...out, lidTracked: { left: share(LIDS.left), right: share(LIDS.right) } };
  }

  /**
   * Eye-closure mirror step (FPA-GEOM 0.5.0) for the frames picked for `key`: frames where an eye's lid points were
   * not tracked get `mirrorClosure` (in place, on the observations already handed out). Run with the camera stopped:
   * `detect` switches the landmarker to image mode.
   */
  async addMirror(key: string, detect: Detect): Promise<number> {
    const p = this.picked.get(key);
    if (!this.ref?.gray || !p) return 0;
    const need = (i: number) => {
      const t = p.obs[i]?.lidTracked;
      return !!t && Math.min(t.left, t.right) < LID_TRACKED_MIN;
    };
    const res = await mirrorClosures(this.ref, this.ref.gray, p.grays, detect, need);
    let n = 0;
    res.forEach((r, i) => {
      if (r && p.obs[i]) {
        p.obs[i]!.mirrorClosure = r;
        n++;
      }
    });
    return n;
  }

  /**
   * Frames for the analysis of one recorded task: the ≤ maxN frames the analysis would pick
   * (strongest movement by the detection, rest: evenly spread), tracked from the reference.
   * Without a reference or grabbed frames the detections are returned unchanged.
   */
  trackTask(task: TaskId, frames: readonly FrameObservation[], grabbed: readonly Grabbed[], maxN = 12): FrameObservation[] {
    if (!this.ref || grabbed.length === 0) return [...frames];
    if (task === 'rest') return [this.ref.obs, ...this.trackEven(frames, grabbed, maxN)];
    let pick: Grabbed[];
    const raft = !!this.raft && RAFT_TASKS.has(task);
    if (raft) maxN = Math.min(maxN, Math.max(1, this.raftFrames));
    {
      const restRef = buildRestReference([this.ref.obs, this.ref.obs, this.ref.obs], this.quality);
      if (!restRef) return [...frames];
      pick = grabbed
        .map((g) => {
          const v = measureLive(task as MovementTaskId, restRef, g.obs, this.quality);
          return { g, s: v ? taskSignal(v) : -Infinity };
        })
        .filter((x) => x.s > -Infinity)
        .sort((a, b) => b.s - a.s)
        .slice(0, maxN)
        .map((x) => x.g);
    }
    const out = this.trackAll(pick);
    this.picked.set(task, { grays: pick.map((g) => g.gray), obs: out });
    if (raft) {
      const pool = this.raftPool.get(task) ?? [];
      this.raftPick.set(task, pick.map((g) => pool.find((x) => x.obs === g.obs)?.crop ?? null));
    }
    return out;
  }

  /**
   * ≤ maxN frames spread evenly over a recording (the rise and the hold alike: the synkinesis finder
   * correlates regions over time), tracked from the reference. Detections without a reference.
   */
  trackEven(frames: readonly FrameObservation[], grabbed: readonly Grabbed[], maxN = 16, key?: string): FrameObservation[] {
    if (!this.ref || grabbed.length === 0) return [...frames];
    const step = Math.max(1, grabbed.length / maxN);
    const pick = Array.from({ length: Math.min(maxN, grabbed.length) }, (_, k) => grabbed[Math.floor(k * step)]!);
    const out = this.trackAll(pick);
    if (key) this.picked.set(key, { grays: pick.map((g) => g.gray), obs: out });
    return out;
  }

  private trackAll(pick: readonly Grabbed[]): FrameObservation[] {
    let kept = 0;
    const out = pick.map((g) => {
      const o = this.track(g);
      kept += this.lastKept;
      return o;
    });
    this.lastKept = pick.length ? kept / pick.length : 0;
    return out;
  }

  private draw(src: CanvasImageSource, w: number, h: number, t: [number, number, number, number, number, number]): Gray | null {
    const c = (this.canvas ??= document.createElement('canvas'));
    if (c.width !== w) c.width = w;
    if (c.height !== h) c.height = h;
    const ctx = c.getContext('2d', { willReadFrequently: true });
    if (!ctx) return null;
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, w, h);
    ctx.setTransform(...t);
    ctx.drawImage(src, 0, 0);
    const d = ctx.getImageData(0, 0, w, h).data;
    const data = new Uint8Array(w * h);
    for (let i = 0; i < w * h; i++) data[i] = (77 * d[4 * i]! + 150 * d[4 * i + 1]! + 29 * d[4 * i + 2]!) >> 8;
    return { w, h, data };
  }
}
